"""Simple assertion to check if function GraphQL validation was successful.

This assertion checks if the validate_graphql_codeblocks tool from dev-mcp was called and validated successfully
when validating function input GraphQL queries.
"""

import os
import sys
from typing import Any, Dict

# Fix import path for when script is run directly
current_dir = os.path.dirname(os.path.abspath(__file__))
if current_dir not in sys.path:
    sys.path.insert(0, current_dir)

from utils.validation_parser import (
    check_tool_called,
    find_last_tool_call,
    is_validation_successful,
    parse_validation_block,
    summarize_failure,
)


def get_assert(output: str, context: Dict[str, Any]) -> Dict[str, Any]:
    """Check if function GraphQL validation was successful.

    This assertion looks for:
    1. Whether the validate_graphql_codeblocks tool was called
    2. Whether the validation was successful

    Args:
        output: The full output from the agent
        context: The context containing prompt and other data

    Returns:
        Dict with pass/fail status, score, and reason
    """
    # Check if validate_graphql_codeblocks tool was called
    tool_called = check_tool_called(output, "validate_graphql_codeblocks")
    if not tool_called:
        return {
            "pass": False,
            "score": 0,
            "reason": "validate_graphql_codeblocks tool was not called",
        }

    # Check if validation was successful
    validation_successful = is_validation_successful(
        output, "validate_graphql_codeblocks"
    )
    if not validation_successful:
        # Extract detailed failure reason
        failure_reason = "validate_graphql_codeblocks tool was called but validation failed"
        tool_call = find_last_tool_call(output, "validate_graphql_codeblocks")
        if tool_call:
            try:
                validation_result = parse_validation_block(tool_call.output)
                # Use the summarize_failure function for a clean error message
                failure_reason = summarize_failure(validation_result, "GraphQL validation")
            except Exception:
                # If parsing fails, use the generic message
                pass

        return {
            "pass": False,
            "score": 0.5,
            "reason": failure_reason,
        }

    return {
        "pass": True,
        "score": 1.0,
        "reason": "validate_graphql_codeblocks tool was called successfully",
    }
